WITH lines AS (SELECT id, created_at, coupon_codes, pos, rec.qty, rec.price, rec.promo FROM carts LATERAL VIEW POSEXPLODE(items) x AS pos, rec), lines_carts AS (SELECT id, created_at, pos, qty, price, promo, EXPLODE(coupon_codes) AS code FROM lines), valid AS (SELECT id, created_at, pos, qty, price, code, DATEDIFF(CURRENT_DATE(), created_at) AS days_since_created_at, CONCAT_WS('/', promo, code) AS promo_code_key FROM lines_carts WHERE created_at >= TO_TIMESTAMP('2025-03-01 13:00:00') AND created_at >= '2024-02-01'), valid_carts AS (SELECT *, CASE WHEN code IN ('VIP', 'WELCOME5') THEN 'Priority' ELSE 'Other' END AS code_group, qty * days_since_created_at AS qty_times_days_since_created_at, COALESCE(code, 'DIRECT') AS code_filled FROM valid WHERE created_at > TIMESTAMP '2025-03-01 10:00:00' AND code IS NOT DISTINCT FROM 'BUNDLE') SELECT CASE WHEN price >= 211 THEN 'LARGE' ELSE 'SMALL' END AS price_tier, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, MIN(created_at) AS first_seen FROM valid_carts GROUP BY price_tier
